          s.push_back(ws(3, "BODY: wear a leather apron or flame-retardant jacket and full-sleeve cotton clothes. Button the collar and cuffs. Avoid nylon or other synthetic clothes (they melt), rolled sleeves or open pockets that catch spatter.", {{"clothing", "leather apron, cotton"}}, {"apron"}));
